// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2008,"grade":"8-11","contest":"Золотое руно","letters":"DN?","count":90,"language":"ru","points":3,"tasksFile":"tasks-8-11.pdf","answersFile":"reviewed-8-11.pdf","sections":[{"start":1,"title":"1861–1870"},{"start":19,"title":"1871–1880"},{"start":37,"title":"1881–1890"},{"start":55,"title":"1891–1900"},{"start":73,"title":"1901–1914"}],"reviewedKey":true}, [{"question":"Вместе с Аляской Россия продает США Алеутские острова.","context":"1861–1870. Изменение карты россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Острова при продаже Аляски","steps":["В договоре 1867 года перечислены земли Российской Америки, которые переходили Соединённым Штатам.","В число переданных территорий входили Алеутские острова. Утверждение верно."]},{"question":"Отделение от России Бухарского ханства.","context":"1861–1870. Изменение карты россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Статус Бухарского ханства","steps":["После договоров и военных событий второй половины XIX века Бухарский эмират сохранил местного правителя и оказался в зависимости от Российской империи.","Он был её протекторатом. Отделения от России в 1871–1880 годах не было."]},{"question":"В этот период Сахалин становится полностью российской территорией.","context":"1861–1870. Изменение карты россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Статус Сахалина","steps":["После договора 1855 года Россия и Япония так и не разделили остров точной границей. Обе стороны продолжали претендовать на Сахалин.","Япония отказалась от прав на Сахалин по договору 1875 года в обмен на Курильские острова. 1865 год не подходит."]},{"question":"Устав о всеобщей воинской повинности приняли при Александре II в 1861–1870 годах.","context":"1861–1870. Деятельность александра ii","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Устав о воинской повинности","steps":["Реформирование армии началось при Александре II в 1860-х годах. Правила о всеобщей воинской повинности были отдельной частью преобразований.","Устав приняли в январе 1874 года. Эта дата выходит за указанный период."],"reviewedEdition":true},{"question":"Манифест о «незыблемости» самодержавия.","context":"1861–1870. Деятельность александра ii","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Манифест о самодержавии","steps":["Манифест подтвердил приверженность самодержавию после гибели Александра II. Его издал новый император Александр III.","Документ относится к 1881 году. Для периода 1861–1870 утверждение неверно."]},{"question":"Судебная реформа. Судебная власть отделяется от административной и становится независимой.","context":"1861–1870. Деятельность александра ii","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Отделение судебной власти","steps":["Судебные уставы 1864 года установили независимость судебных учреждений, правила открытого судопроизводства и ряд других изменений.","Судебная реформа действительно входит в период 1861–1870. Судебные органы отделялись от административных властей."]},{"question":"Пруссия ведет войны за гегемонию в Германии.","context":"1861–1870. Формирование германской империи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Пруссия и немецкие земли","steps":["В 1860-х Пруссия боролась за ведущее положение среди немецких государств. В 1866 году она победила Австрию и её союзников.","После этого Пруссия возглавила Северогерманский союз, а в 1870 году начала войну с Францией. Период в условии подходит."]},{"question":"Франко-прусская война продолжается 30 дней.","context":"1861–1870. Формирование германской империи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Длительность войны","steps":["Франко-прусская война началась в июле 1870 года. После пленения Наполеона III в сентябре бои ещё продолжались.","Франкфуртский мир заключили в мае 1871 года. Продолжительность войны существенно больше тридцати дней."]},{"question":"В 1870 году в Версале провозглашается Германская империя.","context":"1861–1870. Формирование германской империи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Провозглашение империи","steps":["В 1870 году Пруссия и южногерманские государства договорились об объединении. Торжественную церемонию провели в Версальском дворце.","Вильгельма I провозгласили германским императором 18 января 1871 года. В условии указан предыдущий год."]},{"question":"Показанный на фотографии памятник открыли к тысячелетию России.","context":"1861–1870. Памятники русской истории","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Юбилейный памятник","steps":["На многоярусном памятнике собраны фигуры исторических деятелей. Верхняя часть напоминает державу, один из символов российской государственной власти.","Это «Тысячелетие России» в Великом Новгороде. Памятник открыли в 1862 году к тысячелетнему юбилею."],"figure":{"src":"assets/golden-fleece/2008/2008_57_II-10.jpg","alt":"На каменном постаменте несколько ярусов фигур, наверху фигуры у державы.","width":307,"height":484},"adaptation":"Фотография для учебного задания подобрана редакцией Olympiads.pro.","reviewedEdition":true},{"question":"Конный памятник Николаю I, показанный на фотографии, находится в Париже.","context":"Памятники русской истории. Проверьте подпись к снимку.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Памятник Николаю I","steps":["Высокий пьедестал с рельефами и скульптурными фигурами поддерживает конную статую. По этим деталям узнаётся памятник Николаю I.","Памятник стоит на Исаакиевской площади в Санкт-Петербурге. В подписи указан другой город."],"figure":{"src":"assets/golden-fleece/2008/2008_57_II-11.jpg","alt":"Конная статуя над высоким постаментом с рельефами.","width":307,"height":484},"adaptation":"Фотография для учебного задания подобрана редакцией Olympiads.pro.","reviewedEdition":true},{"question":"На фотографии памятник Александру I на Сенатской площади в Хельсинки.","context":"Памятники русской истории. Проверьте подпись к снимку.","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Памятник в Хельсинки","steps":["За памятником виден лютеранский собор Хельсинки. Монумент стоит перед ним на Сенатской площади.","Памятник посвящён императору Александру II. Город в подписи указан правильно, номер императора ошибочен."],"figure":{"src":"assets/golden-fleece/2008/2008_57_II-12.jpg","alt":"Памятник с фигурой наверху и фигурами у основания на фоне светлого собора.","width":307,"height":484},"adaptation":"Фотография для учебного задания подобрана редакцией Olympiads.pro.","reviewedEdition":true},{"question":"Роман Ф. Достоевского «Преступление и наказание» был опубликован в 1866 году в восьми номерах журнала «Русский вестник».","context":"1861–1870. Русская литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Роман в «Русском вестнике»","steps":["Достоевский впервые публиковал «Преступление и наказание» по частям в 1866 году. С публикациями можно свериться в выпусках «Русского вестника».","Части появились в январском, февральском, апрельском, июньском, июльском, августовском, ноябрьском и декабрьском выпусках. Это восемь номеров."]},{"question":"В статье «Старое барство» Дмитрий Писарев разбирал роман Льва Толстого «Война и мир».","context":"1861–1870. Русская литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Критика «Войны и мира»","steps":["Писарев читал первые тома «Войны и мира». В своём отклике он обсуждал, как Толстой показывает дворянское общество и, в частности, Николая Ростова.","В 1868 году журнал «Отечественные записки» напечатал статью Писарева «Старое барство». Утверждение верно."],"adaptation":"Учебный вопрос об определённой статье о романе «Война и мир».","reviewedEdition":true},{"question":"Начинается публикация «Толкового словаря живого великорусского языка» В. Даля.","context":"1861–1870. Русская литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Публикация словаря Даля","steps":["Владимир Даль много лет записывал слова и выражения живой речи. Его толковый словарь вышел несколькими томами.","Первые издания томов относятся к 1863–1866 годам. Начало публикации попадает в заданный отрезок."]},{"question":"Название кружку дал А. Рубинштейн.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кто дал название кружку","steps":["В 1867 году критик отозвался о произведениях молодых русских композиторов и употребил выражение «могучая кучка». Позднее оно стало названием кружка.","Критика звали Владимир Стасов. Антон Рубинштейн основал Петербургскую консерваторию, но название кружку дал не он."]},{"question":"Санкт-Петербургская консерватория была основана в 1862 году одним из членов «Могучей кучки».","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Основание консерватории","steps":["Санкт-Петербургская консерватория открылась в 1862 году. Одним из её основных организаторов и первым директором был Антон Рубинштейн.","Рубинштейн не входил в «Могучую кучку». Дата указана верно, связь с составом кружка ошибочна."]},{"question":"Оркестровое произведение Балакирева «1000 лет», связанное с юбилеем России, появилось в 1860-х годах.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Увертюра и памятник","steps":["Симфоническая картина «1000 лет» посвящена истории страны. Балакирев работал над ней в первой половине 1860-х годов.","Ранняя редакция относится к 1863–1864 годам. Название «Русь» Балакирев дал более поздней переработке произведения."],"reviewedEdition":true},{"question":"Создание I Интернационала.","context":"1871–1880. Общественно-политические движения в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первый Интернационал","steps":["Международное товарищество рабочих образовалось на собрании в Лондоне. Организацию также называют Первым Интернационалом.","Создание относится к 1864 году, раньше периода 1871–1880."]},{"question":"Падение Парижской коммуны.","context":"1871–1880. Общественно-политические движения в европе","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Конец Парижской коммуны","steps":["Весной 1871 года в Париже действовала Коммуна. В мае войска правительства взяли город.","Коммуна прекратила существование к концу мая 1871 года. Это начало указанного периода."]},{"question":"Легализация профсоюзов в Англии и Франции.","context":"1871–1880. Общественно-политические движения в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Легализация профсоюзов","steps":["Британский закон признал профсоюзы в 1871 году. Во Франции законодательное разрешение профсоюзов вступило в силу в 1884-м.","Из двух дат отрезку 1871–1880 соответствует только британская. Общее утверждение о двух странах неверно."]},{"question":"Образование партии «Народная воля».","context":"1871–1880. Активизация общественно-политических движений в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Образование «Народной воли»","steps":["В 1879 году организация «Земля и воля» разделилась. Одна из возникших групп стала называться «Народной волей».","1879 год входит в период 1871–1880. Утверждение верно."]},{"question":"Покушение В. Засулич на Александра II .","context":"1871–1880. Активизация общественно-политических движений в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"На кого покушалась Засулич","steps":["В январе 1878 года Вера Засулич выстрелила в петербургского градоначальника Фёдора Трепова. Суд присяжных позднее её оправдал.","Александр II не был целью этого покушения. Дата подходит к периоду, имя в условии неверно."]},{"question":"В состав партии «Народная воля» входили С. Перовская, А. Желябов и С. Халтурин.","context":"1871–1880. Активизация общественно-политических движений в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Участники «Народной воли»","steps":["Софья Перовская и Андрей Желябов входили в руководящие круги «Народной воли». Степан Халтурин участвовал в революционной деятельности и также примкнул к организации.","Все три имени относятся к истории «Народной воли». Утверждение о составе верно."]},{"question":"О. Ренуар.","context":"1871–1880. Появление полотен импрессионистов. определите, правильно ли указаны их авторы","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Художник и порт в тумане","figure":{"src":"assets/golden-fleece/2008/2008_811_III-28.jpg","alt":"Лодки в туманном порту и ярко-оранжевое солнце над водой.","width":425,"height":319},"steps":["Над водой виден красноватый восход, а на переднем плане — лодка. Это «Впечатление. Восход солнца», связанное с названием импрессионизма.","Автор — Клод Моне. В подписи указано имя другого импрессиониста, Огюста Ренуара."]},{"question":"К. Моне.","context":"1871–1880. Появление полотен импрессионистов. определите, правильно ли указаны их авторы","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Балетный класс на холсте","figure":{"src":"assets/golden-fleece/2008/2008_811_III-29.jpg","alt":"Балерины в белых платьях в репетиционном зале.","width":496,"height":496},"steps":["Танцовщицы в белых платьях находятся в репетиционном зале. Этот сюжет много раз рисовал один и тот же французский художник.","Сцену написал Эдгар Дега. Подпись указывает Клода Моне, который прославился другими сюжетами."]},{"question":"Э. Дега.","context":"1871–1880. Появление полотен импрессионистов. определите, правильно ли указаны их авторы","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Люди на открытом балу","figure":{"src":"assets/golden-fleece/2008/2008_811_III-30.jpg","alt":"Многолюдный бал под открытым небом, на переднем плане стол и сидящие люди.","width":425,"height":307},"steps":["На картине множество людей сидят и танцуют под деревьями. Полотно известно как «Бал в Мулен де ла Галетт».","Его написал Огюст Ренуар. Эдгар Дега, указанный в подписи, не является автором."]},{"question":"Начало публикации сатирических произведений М. Салтыкова-Щедрина.","context":"1871–1880. Расцвет русского реализма","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Ранние сатиры Щедрина","steps":["Салтыков-Щедрин прославился «Губернскими очерками», которые начали печатать в 1850-х годах.","В последующие десятилетия выходили другие его произведения. Начало сатирических публикаций не относится к 1871–1880 годам."]},{"question":"Выход в свет романов «Анна Каренина» и «Бесы».","context":"1871–1880. Расцвет русского реализма","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Две публикации романов","steps":["«Бесы» Достоевского выходили в журнале в 1871–1872 годах. «Анна Каренина» Толстого печаталась по частям с 1875 по 1877 год.","Отдельные книжные издания тоже появились в 1870-х. Оба романа укладываются в указанный период."]},{"question":"Появление журнала Ф. Достоевского «Дневник писателя».","context":"1871–1880. Расцвет русского реализма","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"«Дневник писателя»","steps":["Сначала Достоевский публиковал «Дневник писателя» как рубрику журнала «Гражданин» с 1873 года. Позднее он стал выпускать «Дневник» отдельно.","Первые самостоятельные выпуски появились в 1876 году. Оба этапа относятся к указанному десятилетию."]},{"question":"Опера П. Чайковского «Евгений Онегин» впервые ставится в 1879 году в Мариинском театре.","context":"1871–1880. Оперные постановки, определившие развитие европейского музыкального театра","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первая сцена «Онегина»","steps":["Первую постановку «Евгения Онегина» в 1879 году подготовили учащиеся Московской консерватории. Её представили в Малом театре в Москве.","Мариинский театр поставил оперу позднее, в 1884 году. В утверждении перепутано место первой постановки."]},{"question":"Грандиозный успех первой постановки оперы Ж. Бизе «Кармен».","context":"1871–1880. Оперные постановки, определившие развитие европейского музыкального театра","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первая постановка «Кармен»","steps":["Опера Бизе впервые прозвучала в Париже в 1875 году. Новая музыка и необычный для театра сюжет вызвали неоднозначные отзывы.","Большая международная популярность пришла к опере позже. Говорить о грандиозном успехе её первой постановки нельзя."]},{"question":"Премьера тетралогии Р. Вагнера «Кольцо Нибелунга».","context":"1871–1880. Оперные постановки, определившие развитие европейского музыкального театра","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Премьера тетралогии","steps":["«Кольцо Нибелунга» объединяет четыре оперы Вагнера. Некоторые части показали до первого полного исполнения.","Весь цикл впервые представили в Байройте в 1876 году. Это входит в период 1871–1880."]},{"question":"Д. Менделеев в 1879 году открывает периодический закон химических элементов.","context":"1871–1880. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Год периодического закона","steps":["Дмитрий Менделеев начал публиковать систему элементов и формулировку периодического закона в 1869 году.","1879 год на десять лет позже. Указанная дата открытия неверна."]},{"question":"И. Сеченов публикует работу «Рефлексы головного мозга».","context":"1871–1880. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Труд о рефлексах","steps":["В работе «Рефлексы головного мозга» Иван Сеченов объяснял, как деятельность мозга связана с рефлекторными процессами.","Впервые работу опубликовали в 1863 году. Период 1871–1880 для её появления не подходит."]},{"question":"Т. Эдисон в 1877 изобретает фонограф – первый прибор для записи и воспроизведения звука.","context":"1871–1880. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Запись и воспроизведение","steps":["До фонографа существовали приборы, которые оставляли след звуковых колебаний. Особенность фонографа заключалась в том, что запись можно было снова услышать.","Томас Эдисон представил фонограф в 1877 году. Имя изобретателя и дата указаны верно."]},{"question":"Деятельность провокатора С. Дегаева.","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Деятельность Дегаева","steps":["Сергей Дегаев участвовал в «Народной воле», а после ареста стал передавать полиции сведения о революционерах. Его связали с выдачей нескольких участников организации.","Это произошло в начале 1880-х годов. Указанный отрезок 1881–1890 подходит."]},{"question":"После убийства 1 марта 1881 года царя Александра II российский трон переходит к Николаю II .","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Преемник Александра II","steps":["Александр II погиб в 1881 году. Престол занял его сын, ставший Александром III.","Николай II, сын Александра III, начал царствовать в 1894 году. В задании пропущено одно правление."]},{"question":"В 1887 году принят закон об ограничении гласности суда.","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Гласность суда","steps":["Судебные реформы 1860-х сделали процессы более открытыми для публики. В конце 1880-х возможность проводить закрытые заседания расширили.","Закон, ограничивавший гласность судебных заседаний, относится к 1887 году. Дата в условии соответствует периоду."]},{"question":"«Подсолнухи».","context":"1881–1890. В. ван гог. определите, верны ли названия картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Ночь над рекой","figure":{"src":"assets/golden-fleece/2008/2008_811_III-43.jpg","alt":"Ночное небо над рекой, огни на берегу и длинные отражения на воде.","width":449,"height":307},"steps":["На репродукции ночное небо и вода, в которой отражаются огни. Это «Звёздная ночь над Роной» Винсента ван Гога.","«Подсолнухи» у того же художника изображают цветы. Название в условии не подходит к этому полотну."]},{"question":"«Звездная ночь».","context":"1881–1890. В. ван гог. определите, верны ли названия картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Ваза и жёлтые цветы","figure":{"src":"assets/golden-fleece/2008/2008_811_III-44.jpg","alt":"Жёлтые цветы в высокой вазе на жёлтом фоне.","width":402,"height":508},"steps":["На картине жёлтые цветы в вазе. Винсент ван Гог написал серию натюрмортов с такими цветами.","Картину относят к «Подсолнухам». «Звёздная ночь» показывает совсем другой сюжет."]},{"question":"«Автопортрет».","context":"1881–1890. В. ван гог. определите, верны ли названия картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Художник за работой","figure":{"src":"assets/golden-fleece/2008/2008_811_III-45.jpg","alt":"Сидящий художник работает, перед ним мольберт и цветы.","width":461,"height":319},"steps":["На картине Ван Гог пишет подсолнухи. Самого Ван Гога изобразил его коллега Поль Гоген.","Поскольку художник на картине и её автор — разные люди, подпись «Автопортрет» неверна."]},{"question":"Выход на русском языке перевода первого тома «Капитала» К. Маркса.","context":"1881–1890. Новые философские течения","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Русское издание «Капитала»","steps":["Первый том «Капитала» Маркс опубликовал на немецком в 1867 году. Первое русское издание появилось спустя несколько лет.","Русский перевод первого тома вышел в Петербурге в 1872 году. Указанный отрезок 1881–1890 слишком поздний."]},{"question":"Ф. Ницше выдвигает идею «сверхчеловека» в своей книге «Так говорил Заратустра».","context":"1881–1890. Новые философские течения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Заратустра и сверхчеловек","steps":["В философской книге Ницше персонаж Заратустра говорит о преодолении привычных представлений о человеке. С этим связано понятие сверхчеловека.","Части книги создавались и печатались в 1880-х годах. Автор, произведение и период указаны верно."]},{"question":"Русский философ В. Соловьев пропагандирует идею воссоединения Западной и Восточной Церквей под главенством Римского Папы.","context":"1881–1890. Новые философские течения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Философ о единстве церквей","steps":["Владимир Соловьёв писал о сближении восточного и западного христианства. В книге «Россия и Вселенская церковь» он рассматривал роль папы в единой церкви.","Книга вышла в 1889 году. Идея и время подходят к данному утверждению."]},{"question":"Первый номер журнала «Вокруг света» вышел в 1885 году.","context":"1881–1890. Русская литература на переломе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Когда появились журналы","steps":["Журнал «Вокруг света» о путешествиях начал выходить в 1861 году. Через несколько лет его выпуск прервался.","В 1885 году выпуск возобновили. Первый номер журнала вышел раньше, поэтому утверждение неверно."],"reviewedEdition":true},{"question":"Первая публикация А. Чехова в 1881 году.","context":"1881–1890. Русская литература на переломе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Литературный дебют Чехова","steps":["Чехов начал печататься в юмористических журналах. «Письмо к учёному соседу» появилось в журнале «Стрекоза».","Это издание вышло в 1880 году. Для первой публикации указанный 1881 год неверен."]},{"question":"Публикуются стихотворные сборники Н. Минского, К. Случевского, К. Фофанова – провозвестников русского символизма.","context":"1881–1890. Русская литература на переломе","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Ранние символисты","steps":["В 1880-х читатели познакомились со стихотворными сборниками Николая Минского, Константина Случевского и Константина Фофанова.","В литературе их часто относят к предшественникам русского символизма. Время публикаций соответствует периоду."]},{"question":"В 1882 году в Лондоне пущена первая линия метро.","context":"1881–1890. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Начало лондонского метро","steps":["Первая линия в Лондоне связала станции Паддингтон и Фаррингдон. На ней использовали паровые поезда.","Она открылась в 1863 году. Указанный 1882 год не подходит."]},{"question":"В 1883 году Р. Дизель изобретает двигатель внутреннего сгорания.","context":"1881–1890. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Двигатель Дизеля","steps":["Принцип двигателей с внутренним сгоранием был известен до работ Рудольфа Дизеля. Он разработал собственный способ воспламенять топливо за счёт сжатия.","Дизель запатентовал свой принцип в 1890-х, а работоспособный двигатель испытали в 1897 году. Дата 1883 неверна."]},{"question":"Джесси Рено запатентовал наклонный подъёмник, предшественник эскалатора, в 1881–1890 годах.","context":"1881–1890. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Патент на движущийся подъём","steps":["Рено предложил наклонную движущуюся ленту, на которой могли стоять пассажиры. В ней ещё не было привычных подвижных ступеней.","Американский патент выдали в 1892 году, за пределами указанного периода."],"reviewedEdition":true},{"question":"В своих путешествиях Н. Пржевальский достигает Индии.","context":"1881–1890. Великие путешественники","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Маршруты в Азии","steps":["Пржевальский исследовал территории Монголии, северного Китая и Тибета. Индия лежала южнее основных районов его исследований.","До Индии его экспедиции не дошли. Утверждение неверно."]},{"question":"Ф. Нансен пересекает на лыжах остров Гренландия.","context":"1881–1890. Великие путешественники","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Путь через Гренландию","steps":["Норвежский исследователь Фритьоф Нансен и его спутники пересекли ледниковый щит Гренландии на лыжах. Они прошли с восточного берега на западный.","Поход состоялся в 1888 году. Эта дата входит в указанный отрезок."]},{"question":"Первое восхождение на Эверест.","context":"1881–1890. Великие путешественники","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первое восхождение на Эверест","steps":["Первое подтверждённое восхождение на высочайшую вершину мира совершили Эдмунд Хиллари и Тенцинг Норгей.","Это произошло в мае 1953 года. Для периода 1881–1890 событие слишком позднее."]},{"question":"Завершается строительство Панамского канала.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Даты Панамского канала","steps":["Французская компания начала работы на Панамском перешейке в 1881 году. После перерыва строительство продолжили под руководством США.","Канал официально открыли в 1914 году. В 1891–1900 годах работы не завершились."]},{"question":"В 1893 году начинается регулярное сообщение по Транссибирской железнодорожной магистрали.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Сообщение по Транссибу","steps":["Большую Сибирскую магистраль начали строить в 1891 году. Регулярное движение по отдельным участкам и сквозное сообщение появились в разные даты.","В 1893 году сквозного сообщения по магистрали ещё не было. Транссиб строили и в следующем десятилетии."]},{"question":"Историю Новосибирска отсчитывают от появления в 1893 году поселения строителей железнодорожного моста через Обь.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Основание Новониколаевска","steps":["В 1893 году рядом со стройкой моста через Обь появилось постоянное поселение. Из него вырос Ново-Николаевск, современный Новосибирск.","1893 год считается началом истории поселения. Статус города Ново-Николаевск получил позднее, в 1903 году по старому стилю."],"reviewedEdition":true},{"question":"Э. Золя выступает с открытым письмом «Я обвиняю» в связи с делом А. Дрейфуса.","context":"1891–1900. Общественные движения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Открытое письмо Золя","steps":["Эмиль Золя опубликовал письмо президенту Франции в газете L’Aurore. Он выступал в защиту Альфреда Дрейфуса и критиковал ход дела.","Письмо «Я обвиняю» появилось в 1898 году. Имя, содержание и период согласуются с утверждением."]},{"question":"В 1900 году в Великобритании создали Комитет рабочего представительства, предшественник Лейбористской партии.","context":"1891–1900. Общественные движения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Начало Лейбористской партии","steps":["Профсоюзы и социалистические организации объединились для представительства рабочих в британском парламенте.","Комитет рабочего представительства образовали в 1900 году. Название «Лейбористская партия» закрепилось за ним в 1906-м."],"reviewedEdition":true},{"question":"В. Ленин создает «Союз борьбы за освобождение рабочего класса».","context":"1891–1900. Общественные движения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Союз рабочих кружков","steps":["В 1895 году петербургские марксистские кружки объединились в «Союз борьбы за освобождение рабочего класса».","В объединении участвовали Владимир Ленин и Юлий Мартов. Указанное событие входит в заданный период."]},{"question":"П. Сезанн.","context":"1891–1900. Мировая живопись. определите, правильно ли указаны авторы картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Художник и сюжет салона","figure":{"src":"assets/golden-fleece/2008/2008_811_III-61.jpg","alt":"Женщины сидят в комнате с красным диваном и зелёными шторами.","width":437,"height":319},"steps":["На полотне показан салон на улице де Мулен в Париже. Изображения интерьеров и людей в таких заведениях характерны для Анри де Тулуз-Лотрека.","Эта картина принадлежит Тулуз-Лотреку. Поль Сезанн не был её автором."]},{"question":"П. Гоген.","context":"1891–1900. Мировая живопись. определите, правильно ли указаны авторы картин","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Автор тропической сцены","figure":{"src":"assets/golden-fleece/2008/2008_811_III-62.jpg","alt":"Две темноволосые женщины в ярких тканях сидят рядом.","width":484,"height":343},"steps":["На картине изображены две женщины в яркой одежде. Подобные мотивы встречаются в полотнах, которые художник создавал после переезда на Таити.","Это работа Поля Гогена. Его имя в подписи указано верно."]},{"question":"А. Тулуз-Лотрек.","context":"1891–1900. Мировая живопись. определите, правильно ли указаны авторы картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Партия в карты на картине","figure":{"src":"assets/golden-fleece/2008/2008_811_III-63.jpg","alt":"Двое мужчин в шляпах играют в карты за небольшим столом.","width":437,"height":343},"steps":["Двое мужчин сидят за столом с картами в руках. Эта группа принадлежит к серии «Игроки в карты».","Серию написал Поль Сезанн в 1890-х годах. Подпись с именем Тулуз-Лотрека неверна."]},{"question":"А. Белый издает сборники «Русские символисты».","context":"1891–1900. Русский символизм","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Сборники о символизме","steps":["В 1894–1895 годах вышло несколько выпусков сборника «Русские символисты». Их подготовил Валерий Брюсов.","Андрей Белый был одним из известных символистов следующего поколения. Эти сборники издал Брюсов."]},{"question":"Публикуются первые стихотворные сборники В. Брюсова.","context":"1891–1900. Русский символизм","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первые сборники Брюсова","steps":["В 1890-х Брюсов выпустил первые поэтические сборники под собственным именем. Среди них «Chefs d’œuvre» и «Me eum esse».","Эти сборники появились в 1895 и 1897 годах. Оба года входят в указанный период."]},{"question":"Появляются первые публикации Вяч. Иванова.","context":"1891–1900. Русский символизм","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Ранние публикации Иванова","steps":["Стихи Вячеслава Иванова были опубликованы в конце XIX века, в том числе в «Вестнике Европы» и «Космополисе» в 1898 году.","Первый отдельный сборник появился позже. Ранние публикации в периодике укладываются в период 1891–1900."]},{"question":"В Париже состоялись первые премьеры балетов И. Стравинского.","context":"1891–1900. Новые имена в русской музыке","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Первые балеты Стравинского","steps":["Стравинский прославился во Франции благодаря постановкам антрепризы Дягилева. Первой была «Жар-птица» в 1910 году.","Затем последовали «Петрушка» в 1911-м и «Весна священная» в 1913-м. Период 1891–1900 слишком ранний."]},{"question":"Сергей Рахманинов закончил первоначальную редакцию Первого концерта для фортепиано с оркестром в 1891 году.","context":"1891–1900. Новые имена в русской музыке","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первый концерт Рахманинова","steps":["Рахманинов начал делать наброски концерта в 1890 году. В 1891 году он довёл работу над первоначальной редакцией до конца.","Речь о завершении первой редакции, поэтому 1891 год верен. В 1917 году композитор вернулся к концерту и переработал его."],"reviewedEdition":true},{"question":"А. Скрябин сочиняет первую симфонию.","context":"1891–1900. Новые имена в русской музыке","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первая симфония Скрябина","steps":["В первой симфонии Скрябина шесть частей. В её финале хор и солисты поют о силе искусства.","Скрябин работал над произведением на рубеже веков и завершил его в 1900 году. Дата входит в указанный период."]},{"question":"В 1898 году П. Кюри и М. Кюри открывают альфа- и бета-частицы радиоактивного атома.","context":"1891–1900. Научные открытия","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Частицы радиоактивных веществ","steps":["В конце XIX века учёные различили несколько видов излучения ядер. Названия «альфа» и «бета» для двух типов ввёл Эрнест Резерфорд.","Пьер и Мария Кюри в 1898 году открыли полоний и радий. Утверждение приписывает им другое открытие."]},{"question":"В 1899 году Э. Резерфорд открывает радиоактивные элементы радий и полоний.","context":"1891–1900. Научные открытия","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кто открыл радий и полоний","steps":["Пьер Кюри и Мария Склодовская-Кюри исследовали радиоактивность урановой руды. При этих работах в 1898 году обнаружили полоний и радий.","Резерфорд исследовал виды излучения. Имена и годы в утверждении перепутаны."]},{"question":"В 1895 году В. Рентген открывает Х-лучи, названные его именем.","context":"1891–1900. Научные открытия","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Открытие Х-лучей","steps":["Вильгельм Рентген заметил лучи при опытах с разрядной трубкой. Они могли проходить через некоторые непрозрачные материалы.","Это произошло в 1895 году. Х-лучи также называют рентгеновскими."]},{"question":"Первым лауреатом Нобелевской премии по физике был немецкий физик В. Рентген.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первая премия по физике","steps":["За открытие лучей, способных проходить через непрозрачные материалы, присудили первую Нобелевскую премию по физике.","Её получил Вильгельм Рентген в 1901 году. Утверждение верно."]},{"question":"Первым лауреатом нобелевской премии по математике был Д. Гильберт.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Премия по математике","steps":["Нобелевские премии вручают, в частности, за достижения в физике, химии и медицине. Отдельной Нобелевской премии по математике нет.","Давид Гильберт внёс значительный вклад в математику. Лауреатом указанной в вопросе премии он быть не мог."]},{"question":"В 1907 году Р. Киплинг получает Нобелевскую премию по литературе.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Премия Киплингу","steps":["Редьярд Киплинг написал «Книгу джунглей», рассказы и стихотворения. Шведская академия отметила его литературное творчество.","Нобелевскую премию по литературе ему присудили в 1907 году. Утверждение верно."]},{"question":"Толчком к революции стал расстрел демонстрации в Санкт-Петербурге 9 января 1905 года.","context":"1901–1914. 1905 год – кровавый год русской истории","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Январская демонстрация","steps":["В Петербурге рабочие шли с петицией к императору. Войска открыли огонь по демонстрантам. Это событие известно как Кровавое воскресенье.","По действовавшему тогда в России календарю это произошло 9 января 1905 года. Событие стало одним из толчков к революции."]},{"question":"П. Шмидт – один из руководителей Севастопольского восстания.","context":"1901–1914. 1905 год – кровавый год русской истории","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Участник восстания в Крыму","steps":["В ноябре 1905 года в Севастополе выступили моряки. Одним из руководителей стал морской офицер, поднявшийся на борт крейсера «Очаков».","Это лейтенант Пётр Шмидт. Он действительно участвовал в руководстве восстанием."]},{"question":"Всеобщая политическая стачка в Москве началась 7 декабря 1905 года по старому стилю.","context":"1901–1914. 1905 год – кровавый год русской истории","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Дни декабрьского восстания","steps":["Московский совет поддержал начало всеобщей политической стачки. Затем в городе произошли вооружённые столкновения.","7 декабря по старому стилю — дата начала стачки. Вооружённая фаза восстания началась позже."],"reviewedEdition":true},{"question":"В 1906 году Л. Толстой пишет роман «Воскресение».","context":"1901–1914. Л. толстой – совесть эпохи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Последний роман Толстого","steps":["Толстой работал над романом «Воскресение» в 1890-е годы. Опубликован он был в 1899-м.","Дата 1906 не соответствует времени работы над последним романом."]},{"question":"В 1901 году Синод опубликовал определение об отпадении Льва Толстого от Православной церкви.","context":"1901–1914. Л. толстой – совесть эпохи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Решение Синода о Толстом","steps":["Синод заявил, что Церковь не считает Толстого своим членом. Писатель позднее опубликовал ответ на определение.","Определение вышло в «Церковных ведомостях» в 1901 году. Именно это событие описано в утверждении."],"reviewedEdition":true},{"question":"Л. Толстой похоронен в своем имении Ясная Поляна.","context":"1901–1914. Л. толстой – совесть эпохи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Могила Толстого","steps":["Толстой умер в ноябре 1910 года на станции Астапово. Его тело перевезли в родовое имение.","Писателя похоронили в Ясной Поляне. Дата и место соответствуют условию."]},{"question":"Начинается деятельность К. Станиславского – крупнейшего реформатора театра.","context":"1901–1914. События в жизни театра","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Начало работы Станиславского","steps":["Станиславский занялся любительским театром в XIX веке. В 1898 году он вместе с Немировичем-Данченко открыл Московский Художественный театр.","В начале XX века он продолжал реформировать театр и развивал свою систему. Деятельность началась ещё до 1901 года."]},{"question":"С. Дягилев организует «Русские сезоны» в Париже.","context":"1901–1914. События в жизни театра","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Кто устроил «Русские сезоны»","steps":["Для парижских выступлений организатор собрал композиторов, художников и танцовщиков. Благодаря гастролям многие из них стали известны за пределами России.","Предприятием руководил Сергей Дягилев. Утверждение о нём верно."]},{"question":"Русский балет и его оформление русскими художниками пользуются наибольшей популярностью в «Русских сезонах».","context":"1901–1914. События в жизни театра","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Балет и сценическое оформление","steps":["На парижских гастролях Дягилева зрителей привлекало сочетание музыки, танца, декораций и костюмов. Например, оформление «Шехеразады» создал Лев Бакст.","Русский балет и работа приглашённых художников сделали «Русские сезоны» особенно известными."]},{"question":"А. Шёнберг изобретает новый метод композиции, получившей название «додекафония».","context":"1901–1914. Смена поколений в музыке этого периода","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Время нового метода","steps":["Додекафония строится на последовательности двенадцати звуков хроматической гаммы. Арнольд Шёнберг разработал этот метод в начале 1920-х годов.","Это позже периода 1901–1914. В условии подходящий композитор назван, но время не подходит."]},{"question":"Первую постановку оперы Рихарда Штрауса «Электра» показали в 1909 году.","context":"1901–1914. Смена поколений в музыке этого периода","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Начало экспрессионизма","steps":["В «Электре» Штраус обратился к древнегреческому сюжету. Драматический характер и напряжённое звучание оперы связывают с ранним экспрессионизмом.","Премьера состоялась в Дрездене в 1909 году. Эта дата входит в указанный период."],"adaptation":"Учебный вопрос о премьере оперы Рихарда Штрауса.","reviewedEdition":true},{"question":"Образуется группа композиторов – «Французская шестерка».","context":"1901–1914. Смена поколений в музыке этого периода","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Французская группа","steps":["«Французской шестёркой» называли композиторов, среди которых были Дариюс Мийо, Франсис Пуленк и Жермена Тайфер. Название вошло в употребление около 1920 года.","Это произошло уже после Первой мировой войны. Период 1901–1914 для образования группы указан неверно."]},{"question":"Венгерская палата депутатов впервые провела заседание в показанном на фотографии здании в 1902 году.","context":"Символы городов мира. Проверьте дату.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Здание у Дуная","figure":{"src":"assets/golden-fleece/2008/2008_57_II-88.jpg","alt":"Длинное здание со шпилями и большим центральным куполом на берегу реки.","width":295,"height":425},"steps":["Неоготический фасад со шпилями и большой центральный купол видны с Дуная. Это здание венгерского парламента в Будапеште.","Библиотека парламента указывает дату первого заседания палаты депутатов в здании — 8 октября 1902 года."],"reviewedEdition":true},{"question":"1906 год.","context":"1901–1914. Символы городов мира. определите, верно ли указаны годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Фигура с факелом","figure":{"src":"assets/golden-fleece/2008/2008_57_II-89.jpg","alt":"Высокая фигура с факелом и короной на каменном постаменте.","width":307,"height":425},"steps":["На снимке Статуя Свободы, установленная на острове в гавани Нью-Йорка.","Памятник открыли в 1886 году. Дата 1906 в подписи неверна."]},{"question":"1912 год.","context":"1901–1914. Символы городов мира. определите, верно ли указаны годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Статуя над городом","figure":{"src":"assets/golden-fleece/2008/2008_24_I-90.jpg","alt":"Высокая статуя с распростёртыми руками на фоне неба.","width":343,"height":425},"steps":["Фигура с распростёртыми руками — статуя Христа-Искупителя на горе Корковаду в Рио-де-Жанейро.","Памятник открыли в 1931 году. В 1912-м статуя ещё не была создана."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
